<lobeArtifact identifier="flask-python-api" type="application/lobe.artifacts.code" language="python" title="Flask API 实现">
from flask import Flask, request, jsonify
from flask_cors import CORS
import numpy as np
import json

app = Flask(__name__)
CORS(app)  # 支持跨域请求

class MeshTopologyGenerator:
    def generate_topology(self, device_info):
        """
        根据设备信息生成拓扑

        :param device_info: 设备信息字典
        :return: 生成的拓扑信息
        """
        # 模拟拓扑生成逻辑
        nodes = [
            {"id": i, "x": np.random.uniform(0, 800), "y": np.random.uniform(0, 600)} 
            for i in range(device_info.get('nodeCount', 16))
        ]

        edges = [
            {
                "from": nodes[i]['id'], 
                "to": nodes[j]['id'], 
                "distance": np.linalg.norm([
                    nodes[i]['x'] - nodes[j]['x'], 
                    nodes[i]['y'] - nodes[j]['y']
                ])
            }
            for i in range(len(nodes)) 
            for j in range(i+1, len(nodes))
        ]

        return {
            "nodes": nodes,
            "edges": edges
        }

@app.route('/generate_topology', methods=['POST'])
def generate_topology():
    """
    接收设备信息并生成拓扑
    """
    try:
        # 接收 JSON 数据
        device_info = request.json

        # 创建拓扑生成器
        generator = MeshTopologyGenerator()

        # 生成拓扑
        topology = generator.generate_topology(device_info)

        # 返回 JSON 响应
        return jsonify({
            "status": "success",
            "data": topology
        })

    except Exception as e:
        return jsonify({
            "status": "error",
            "message": str(e)
        }), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)
