import org.springframework.web.client.RestTemplate;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;

import java.util.HashMap;
import java.util.Map;

public class TopologyApiClient {
    // Flask API 地址
    private static final String API_URL = "http://localhost:5000/generate_topology";

    // RestTemplate 用于发送 HTTP 请求
    private final RestTemplate restTemplate;

    public TopologyApiClient() {
        this.restTemplate = new RestTemplate();
    }

    /**
     * 生成拓扑的方法
     * 
     * @param nodeCount 节点数量
     * @return 拓扑数据
     */
    public Map<String, Object> generateTopology(int nodeCount) {
        // 准备请求头
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);

        // 准备请求体
        Map<String, Object> requestBody = new HashMap<>();
        requestBody.put("nodeCount", nodeCount);
        requestBody.put("minDistance", 200);
        requestBody.put("maxHops", 5);

        // 创建 HTTP 实体
        HttpEntity<Map<String, Object>> request = 
            new HttpEntity<>(requestBody, headers);

        try {
            // 发送 POST 请求并获取响应
            ResponseEntity<Map> response = restTemplate.postForEntity(
                API_URL, 
                request, 
                Map.class
            );

            // 检查响应状态
            if (response.getStatusCode().is2xxSuccessful()) {
                Map<String, Object> responseBody = response.getBody();

                // 假设响应体有 data 字段
                return (Map<String, Object>) responseBody.get("data");
            } else {
                throw new RuntimeException("API 调用失败");
            }
        } catch (Exception e) {
            // 异常处理
            throw new RuntimeException("网络请求错误", e);
        }
    }

    public static void main(String[] args) {
        TopologyApiClient client = new TopologyApiClient();

        try {
            // 生成 20 个节点的拓扑
            Map<String, Object> topology = client.generateTopology(20);

            // 打印节点和边的数量
            System.out.println("节点数量: " + 
                ((List)topology.get("nodes")).size());
            System.out.println("边的数量: " + 
                ((List)topology.get("edges")).size());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
