如果是自己私有化部署的话，可以在服务器加一个nginx规则，对请求进行重写，我这边测试了一下对 Azure AI Foundry 的支持是没问题的
```
location /openai {
    # 提取原始请求路径中的模型名称（DeepSeek-R1）
    if ($request_uri ~* "^/openai/deployments/([^/]+)/chat/completions") {
        set $model_name $1;  # 提取 DeepSeek-R1
    }

    # 将请求路径重写为目标地址
    rewrite ^/openai/deployments/[^/]+/chat/completions$ /models/chat/completions break;

    # 反向代理配置
    proxy_pass Your Endpoint;

    # 请求头设置
    proxy_set_header Host "Your Endpoint";
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header Api-Key "Your API Key";

    # 添加提取的模型名称到请求头
    proxy_set_header X-Ms-Model-Mesh-Model-Name $model_name;

    # 保留原始查询参数
    proxy_set_header X-Original-URI $request_uri;

    # SSL 和超时配置
    proxy_ssl_server_name on;
    proxy_http_version 1.1;
}
```
