@jfjlhc Which issue?

I can confirm the bug. I created a JavaScript script that goes through all files and clicks "Retry" buttons automatically, so it can run quietly in the background.

Here’s a workaround script to run in the Chrome/Edge Dev Console:
========
```javascript
(async () => {
  const scrollStep = 1000;     // Pixels per scroll step
  const scrollDelay = 150;     // ms pause after each scroll step
  const clickDelay = 30000;    // 30 seconds pause after a block of clicks
  const retryClickDelay = 1000; // 1 second pause between clicks

  const container = document.querySelector('div[data-testid="virtuoso-scroller"]');
  if (!container) {
    console.error('Scroll container not found!');
    return;
  }

  // Scroll asynchronously to target position with small steps
  async function scrollTo(position) {
    return new Promise(resolve => {
      const interval = setInterval(() => {
        if (container.scrollTop === position) {
          clearInterval(interval);
          resolve();
        } else {
          if (container.scrollTop < position) {
            container.scrollTop = Math.min(container.scrollTop + scrollStep, position);
          } else {
            container.scrollTop = Math.max(container.scrollTop - scrollStep, position);
          }
        }
      }, scrollDelay);
    });
  }

  // Clicks all visible retry buttons sequentially with delay
  async function clickAllRetries() {
    const retrySelector = 'span[title=Retry]';
    let clickedAny = false;

    while (true) {
      const elems = Array.from(document.querySelectorAll(retrySelector))
        .filter(el => isElementVisibleInContainer(el, container));
      if (elems.length === 0) break;

      clickedAny = true;
      elems.forEach(el => el.click());
      console.log(`Clicked ${elems.length} retry button(s). Waiting 1 second before next check...`);
      await new Promise(r => setTimeout(r, retryClickDelay));
    }

    if (clickedAny) {
      console.log(`Finished clicking retries. Waiting ${clickDelay / 1000} seconds before next check...`);
      await new Promise(r => setTimeout(r, clickDelay));
    } else {
      console.log('No retry buttons found to click.');
    }
    return clickedAny;
  }

  // Check if element is visible inside container viewport
  function isElementVisibleInContainer(el, container) {
    const elRect = el.getBoundingClientRect();
    const contRect = container.getBoundingClientRect();
    return elRect.bottom > contRect.top && elRect.top < contRect.bottom;
  }

  console.log('Starting scroll down to bottom...');
  await scrollTo(container.scrollHeight - container.clientHeight);
  console.log('Reached bottom of scroll container.');

  console.log('Start clicking retries at bottom...');
  await clickAllRetries();

  let currentScroll = container.scrollTop;

  while (currentScroll > 0) {
    const newScroll = Math.max(currentScroll - scrollStep, 0);
    console.log(`Scrolling up from ${currentScroll} to ${newScroll}...`);
    await scrollTo(newScroll);

    console.log('Checking for retry buttons after scrolling up...');
    const clicked = await clickAllRetries();

    if (!clicked) {
      console.log('No retries found at this scroll position, continuing scrolling up...');
    }
    currentScroll = newScroll;
  }

  console.log('Reached top of scroll container. Final check for retries...');
  await clickAllRetries();

  console.log('Process completed.');
})();
``` 
========

**What exactly does the script do?**
Slowly scrolls down all the way to the bottom using scrollTo.
Clicks all visible Retry buttons there (all at once, with 1 second pauses between sets).
Waits 30 seconds after the clicking block.
Then scrolls step-by-step back up, checking and clicking Retry buttons after each step as needed.
Outputs meaningful status messages for every step and click.
Ends once it reaches the top and no retries remain.

**How to use the script:**
Open the page in the Edge browser.
Open Developer Tools (F12).
Switch to the Console tab.
Paste the script and press Enter.


