```
services.AddReverseProxy()
    .AddTransforms(transforms =>
    {
        transforms.AddRequestTransform(context =>
        {
            var query = context.Query.QueryString;
            var path = context.Path;

            // Check whether the path contains @portal or its encoding form %40portal
            if (path.Value.Contains("@portal") || path.Value.Contains("%40portal"))
            {
                var uri = RequestUtilities.MakeDestinationAddress(
                    context.DestinationPrefix,
                    context.Path,
                    query);

                // Create a new URI and disable path normalization
                context.ProxyRequest.RequestUri = new Uri(uri.AbsoluteUri,
                    new UriCreationOptions
                    {
                        DangerousDisablePathAndQueryCanonicalization = true
                    });
            }

            return default;
        });
    });
```

